package app.kinnect.live;
import java.util.*;import java.util.regex.*;import org.json.*;
/** Bounded LRC parser; plain lyrics are shown as text, never given invented timings. */
final class KaraokeLyrics {
 static JSONArray parse(String raw,long duration)throws Exception{if(raw.length()>65536)throw new IllegalArgumentException("lyrics");List<JSONObject> lines=new ArrayList<>();Pattern stamp=Pattern.compile("\\[(\\d{1,2}):(\\d{2})(?:[.:](\\d{1,3}))?\\]");long offset=0;Matcher offsetMatch=Pattern.compile("\\[offset:([+-]?\\d{1,6})\\]").matcher(raw);if(offsetMatch.find())offset=Long.parseLong(offsetMatch.group(1));for(String line:raw.split("\\r?\\n")){Matcher match=stamp.matcher(line);String text=line.replaceAll("\\[[^\\]]*\\]","").trim();if(text.length()>180)text=text.substring(0,180);while(match.find()){int sec=Integer.parseInt(match.group(2));if(sec>59)continue;String fraction=match.group(3);long ms=(Integer.parseInt(match.group(1))*60L+sec)*1000+(fraction==null?0:Math.round(Double.parseDouble("0."+fraction)*1000))+offset;if(ms>=0&&ms<=duration&&!text.isEmpty())lines.add(new JSONObject().put("at",ms).put("text",text));if(lines.size()>500)throw new IllegalArgumentException("lyrics");}}Collections.sort(lines,(a,b)->Long.compare(a.optLong("at"),b.optLong("at")));JSONArray result=new JSONArray();for(JSONObject line:lines)result.put(line);if(result.toString().length()>40000)throw new IllegalArgumentException("lyrics");return result;}
 static int current(JSONArray lines,long ms){int lo=0,hi=lines.length()-1,result=-1;while(lo<=hi){int mid=(lo+hi)>>>1;if(lines.optJSONObject(mid).optLong("at")<=ms){result=mid;lo=mid+1;}else hi=mid-1;}return result;}
}
